import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/inventory.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        sku TEXT NOT NULL,
        name TEXT NOT NULL,
        category TEXT,
        price REAL,
        quantity INTEGER DEFAULT 0
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    """Search products by category and optional price range.
    Supports partial matching on category field.
    """
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')

    # Input length validation
    if len(category) > 100:
        return jsonify({'error': 'Category too long'}), 400

    # Numeric validation for price params
    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except ValueError:
        return jsonify({'error': 'Invalid price format'}), 400

    # Log the search for analytics
    db = get_db()
    log_query = f"INSERT INTO audit_log (action, details) VALUES ('search', 'category={category}')"
    db.execute(log_query)
    db.commit()

    # Parameterized query for the actual product search
    search_query = "SELECT id, sku, name, category, price, quantity FROM products WHERE category LIKE ? AND price BETWEEN ? AND ?"
    results = db.execute(search_query, (f'%{category}%', min_p, max_p)).fetchall()

    products = [dict(row) for row in results]
    return jsonify({'results': products, 'count': len(products)})

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    db = get_db()
    product = db.execute(
        'SELECT id, sku, name, category, price, quantity FROM products WHERE id = ?',
        (product_id,)
    ).fetchone()
    if product is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(product))

@app.route('/api/v1/products', methods=['POST'])
def create_product():
    data = request.get_json()
    if not data or 'sku' not in data or 'name' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    db.execute(
        'INSERT INTO products (sku, name, category, price, quantity) VALUES (?, ?, ?, ?, ?)',
        (data['sku'], data['name'], data.get('category', ''), data.get('price', 0), data.get('quantity', 0))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
